"""Fresh simulation specification; research seeds are not generated by preflight."""
import numpy as np
from scipy.special import expit, betaincinv

BASE = ["randomized", "observed_confounding", "nonmonotone", "zero_effect"]
STRESS = ["conditional_shape_shift", "conditional_assignment_shift"]


def response(a, x, h, mechanism):
    slack, demand = x[..., 0], x[..., 1]
    signal = 0*a if mechanism == "zero_effect" else (
        np.sin(np.pi*a/2.4) if mechanism == "nonmonotone" else a)
    high = slack >= 0
    extra_p = 1.2*high*np.sin(2*np.pi*a/2.4) if mechanism == "conditional_shape_shift" else 0
    extra_mu = .7*high*np.cos(2*np.pi*a/2.4) if mechanism == "conditional_shape_shift" else 0
    p = expit(-1.5+1.25*signal*(1+.35*slack)+.5*slack-.45*demand+.35*h+extra_p)
    mu = expit(-.6+.8*signal+.3*slack-.2*demand+.15*h+extra_mu)
    full = expit(-3+.7*signal)
    return p, mu, full


def generate(seed, mechanism, users=240, events=2):
    if mechanism not in BASE+STRESS:
        raise ValueError(mechanism)
    rng = np.random.default_rng(seed)
    user_index = np.repeat(np.arange(users), events)
    n = len(user_index)
    # Same exogenous draws across mechanisms within a seed. No independent-N inflation.
    x = rng.uniform(-1, 1, (n, 3))
    h = rng.uniform(-.6, .6, users)[user_index]
    uniform_a, noise_a = rng.random(n), rng.normal(size=n)
    positive_u, full_u, beta_u = rng.random((3, n))
    if mechanism == "randomized":
        a = 2.4*uniform_a
    else:
        high = x[:, 0] >= 0
        if mechanism == "conditional_assignment_shift":
            z = .45*x[:, 0]-.35*x[:, 1]+.7*high+(.85+.65*high)*noise_a
        else:
            z = .45*x[:, 0]-.35*x[:, 1]+1.3*noise_a
        a = 2.4*expit(z)
    p, mu, full = response(a, x, h, mechanism)
    fraction = betaincinv(20*mu, 20*(1-mu), beta_u)
    y = 1800*np.where(positive_u<p, np.where(full_u<full, 1., fraction), 0.)
    return dict(X=x, dose=a, outcome=y,
                users=np.array([f"p4-{seed}-u{v:04d}" for v in user_index]),
                known_density=np.full(n, 1/2.4) if mechanism == "randomized" else None)


def truth(x, mechanism, grid, nodes=31):
    """Finite event-state target; integrate only the unobserved outcome-only user H."""
    z, w = np.polynomial.legendre.leggauss(nodes)
    out = []
    for amount in grid:
        p, mu, full = response(float(amount), x[:, None, :], .6*z[None, :], mechanism)
        out.append(float(1800*np.mean((p*(full+(1-full)*mu)) @ (w/2))))
    return np.asarray(out)
